public class Folder {
    protected String name_;
    protected ArrayList<Folder> inside_ = new ArrayList<>();
}

int countFolders() {
    int total = 1;                 // this folder
    for (Folder f : inside_) {
        total += f.countFolders(); // each one counts its own
    }
    return total;
}

